
(function(){function info(){const q=game.rooftop201;roofDiagLab201.textContent=JSON.stringify({phase:q?.phase,seconds:q?.t?.toFixed(2),hero:game.player.type,world:game.environment156?.effective().hour,weather:game.environment156?.effective().weather,knocked:q?.knocked,inside:q?.inside,destination:game.nextLead201});draw();}function start(){game.selectHero(roofHeroLab201.value);sceneSelect.value='bank-rooftop';beginSelectedScene();paused=true;game.environmentPaused156=false;info();document.querySelector('#cabinet').scrollIntoView({block:'center'});}roofStartLab201.onclick=start;roofStageLab201.onclick=()=>{start();let n=0;while(game.rooftop201?.phase!==roofPhaseLab201.value&&n++<2200)game.tick(1/120,{});info();};roofStepLab201.onclick=()=>{for(let i=0;i<60;i++)game.tick(1/120,{});info();};roofNightLab201.onclick=()=>{game.environment156.setOverride({hour:23,weather:'heavyRain',intensity:.9});info();};})();
